Here's a complete data-driven test class using modern MSTest patterns:

```csharp
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ─── CalculateTotal: DataRow approach ───────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_ReturnsExpectedAmount(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative price throws")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax throws")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax > 1 throws")]
    public void CalculateTotal_InvalidInput_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ─── ApplyDiscount: DynamicData approach ────────────────────────────

    [TestMethod]
    [DynamicData(nameof(DiscountTestCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_ReturnsDiscountedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> DiscountTestCases()
    {
        yield return new object[] { 100m, 0m, 100m };    // No discount
        yield return new object[] { 100m, 10m, 90m };    // 10% off
        yield return new object[] { 100m, 50m, 50m };    // Half off
        yield return new object[] { 100m, 100m, 0m };    // Free
        yield return new object[] { 49.99m, 25m, 37.4925m }; // Fractional
        yield return new object[] { 0m, 50m, 0m };       // Zero price
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Discount below 0 throws")]
    [DataRow(100.01, DisplayName = "Discount above 100 throws")]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(50m, (decimal)discount));
    }
}
```

**Key patterns used:**

- **`[DataRow]`** — best for simple inline cases; note `double` params since `DataRow` doesn't support `decimal` literals directly.
- **`[DynamicData]`** — uses a generator method, allowing `decimal` values and more complex setup.
- **`DisplayName`** — makes test explorer output readable.
- **Boundary testing** — zero values, max bounds, and invalid inputs that throw.
- **`Assert.ThrowsException`** with `ParamName` validation for error paths.
